} satisfies Meta<typeof Collapsible>;

export default { ...meta, title: "Components/Collapsible",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

