export const Playground: StoryObj<typeof Collapsible> = {
  argTypes: { defaultOpen: { control: "boolean" }, disabled: { control: "boolean" } },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
